def seed_waiting_external_status(apps, schema_editor):
    Status = apps.get_model('tasks', 'Status')
    Status.objects.update_or_create(
        slug='waiting_external',
        defaults={
            'name': 'Waiting External',
            'description': (
                'Non-terminal dependency wait admitted only by a typed '
                'external-wait authority.'
            ),
            'category': 'todo',
            'color': '#64748b',
            'icon': 'clock',
            'position': 35,
            'is_system': True,
        },
    )


def unseed_waiting_external_status(apps, schema_editor):
    apps.get_model('tasks', 'Status').objects.filter(
        slug='waiting_external'
    ).delete()


