def refuse_reverse_with_live_waits(apps, schema_editor):
    Item = apps.get_model('tasks', 'Item')
    if Item.objects.filter(status='waiting_external').exists():
        raise RuntimeError(
            'Cannot reverse PLS-733 while waiting_external items remain; '
            'disable new admission and drain them through typed release first.'
        )


